* { box-sizing: border-box; }
body { margin: 0; font-family: Inter, system-ui, sans-serif; }

.tilt-stage {
  min-height: 240px;
  display: grid;
  place-items: center;
  padding: 20px;
  background: #0b162a;
  perspective: 900px;
}

.tilt-card {
  position: relative;
  width: min(330px, 100%);
  padding: 24px;
  border-radius: 18px;
  color: #f8fafc;
  background: linear-gradient(145deg, #172d52, #0f1d36);
  border: 1px solid rgba(148, 163, 184, 0.28);
  box-shadow: 0 22px 44px rgba(2, 6, 23, 0.45);
  transform-style: preserve-3d;
  transition: transform 120ms ease-out;
  overflow: hidden;
}

.tilt-card::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(circle at var(--mx, 50%) var(--my, 50%), rgba(125, 211, 252, 0.25), transparent 55%);
  opacity: var(--glare, 0);
  transition: opacity 180ms ease;
}

.tilt-eyebrow {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #38bdf8;
}

.tilt-card h3 { margin: 10px 0 8px; font-size: 20px; }
.tilt-card p { margin: 0; font-size: 14px; line-height: 1.5; color: #cbd5e1; }

